using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.USR.RazasMascota;using GraphApi.Services.USR.RazasMascota;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.USR.RazasMascota{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de RazasMascotas: creación, actualización y eliminación.")]    public class RazasMascotaMutation    {        [Authorize]        [GraphQLName("createRazasMascota")]        [GraphQLDescription("Crea un nuevo RazasMascota usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadRazasMascota> CreateRazasMascotaAsync(            [GraphQLDescription("Datos necesarios para crear el RazasMascota.")]            clCreateRazasMascota objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de RazasMascota.")]            IRazasMascotaService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateRazasMascota(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateRazasMascota")]        [GraphQLDescription("Actualiza los campos especificados de un RazasMascota existente.")]        public async Task<clReadRazasMascota?> UpdateRazasMascotaAsync(            [GraphQLDescription("Datos del RazasMascota a actualizar.")]            clUpdateRazasMascota objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de RazasMascota.")]            IRazasMascotaService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateRazasMascota(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteRazasMascota")]        [GraphQLDescription("Elimina un RazasMascota por su ID.")]        public async Task<bool> delRazasMascotaAsync(            [GraphQLDescription("ID del RazasMascota a eliminar.")]            int nRazasMascotaID,            [Service]            [GraphQLDescription("Servicio para operaciones de RazasMascota.")]            IRazasMascotaService objService        )        {            return await objService.DeleteRazasMascota(nRazasMascotaID);        }    }}